package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var board [4][4]int

	for i := 0; i < 4; i++ {
		for j := 0; j < 4; j++ {
			var c byte
			for {
				b, err := reader.ReadByte()
				if err != nil {
					break
				}
				if b != ' ' && b != '\n' && b != '\r' && b != '\t' {
					c = b
					break
				}
			}
			if c == 'x' {
				board[i][j] = 1
			} else if c == 'o' {
				board[i][j] = -3
			} else {
				board[i][j] = 0
			}
		}
	}

	canWin := false
	for i := 0; !canWin && i < 4; i++ {
		for j := 0; j < 4; j++ {
			if board[i][j] >= 0 {
				sumHor, sumDiaUp, sumDiaDown, sumVer := 0, 0, 0, 0
				if j < 2 {
					sumHor = board[i][j] + board[i][j+1] + board[i][j+2]
				}
				if i < 2 {
					sumVer = board[i][j] + board[i+1][j] + board[i+2][j]
				}
				if i < 2 && j < 2 {
					sumDiaUp = board[i][j] + board[i+1][j+1] + board[i+2][j+2]
				}
				if i >= 2 && j < 2 {
					sumDiaDown = board[i][j] + board[i-1][j+1] + board[i-2][j+2]
				}

				if sumHor == 2 || sumDiaUp == 2 || sumDiaDown == 2 || sumVer == 2 {
					canWin = true
					break
				}
			}
		}
	}

	if canWin {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}
